using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Tool Definitions ---

/// <summary>
/// Provides a simulated web search tool for the research agent.
/// </summary>
static class WebSearchTool
{
    [Description("Searches the web for information on a given query and returns relevant results.")]
    public static string SearchWeb(
        [Description("The search query to look up on the web")] string query)
    {
        // Simulated search results for demonstration purposes.
        var results = query.ToLowerInvariant() switch
        {
            var q when q.Contains("quantum computing") =>
                """
                1. "Quantum Computing Breakthrough 2026" - Researchers at MIT achieved a 1000-qubit stable processor.
                2. "Practical Quantum Algorithms" - New error-correction codes reduce decoherence by 90%.
                3. "Quantum vs Classical" - Current quantum computers now outperform classical systems for optimization problems.
                4. "Industry Adoption" - Major cloud providers offer quantum-as-a-service with hybrid classical-quantum workflows.
                """,
            var q when q.Contains("artificial intelligence") || q.Contains(" ai ") || q.Contains("ai") =>
                """
                1. "AI Agents in 2026" - Autonomous AI agents are now handling complex multi-step workflows.
                2. "Multimodal Models" - Latest models seamlessly process text, images, audio, and video.
                3. "AI Regulation" - The EU AI Act is now fully enforced with compliance frameworks established.
                4. "Open Source AI" - Open-weight models now rival proprietary ones in most benchmarks.
                """,
            _ =>
                $"""
                1. "Overview of {query}" - A comprehensive introduction to {query} and its key concepts.
                2. "Recent Advances in {query}" - Latest research developments and breakthroughs in the field.
                3. "{query} Applications" - Real-world applications and industry use cases.
                4. "Future of {query}" - Expert predictions and emerging trends.
                """
        };

        return $"Search results for '{query}':\n{results}";
    }
}

/// <summary>
/// Provides a note-taking tool that lets the agent collect and organize findings.
/// </summary>
static class NotesTool
{
    private static readonly List<(string Category, string Content)> _notes = [];

    [Description("Saves a research note under a category for later summarization.")]
    public static string SaveNote(
        [Description("The category or heading for the note")] string category,
        [Description("The content of the note to save")] string content)
    {
        _notes.Add((category, content));
        return $"Note saved under '{category}'. Total notes: {_notes.Count}";
    }

    [Description("Retrieves all saved research notes organized by category.")]
    public static string GetAllNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var grouped = _notes
            .GroupBy(n => n.Category)
            .Select(g => $"## {g.Key}\n{string.Join("\n", g.Select(n => $"- {n.Content}"))}");

        return string.Join("\n\n", grouped);
    }
}

// --- Main Program ---

Console.WriteLine("🔬 Research Agent Starting...\n");

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "your-api-key-here";
var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var tools = new AITool[]
{
    AIFunctionFactory.Create(WebSearchTool.SearchWeb),
    AIFunctionFactory.Create(NotesTool.SaveNote),
    AIFunctionFactory.Create(NotesTool.GetAllNotes),
};

var chatOptions = new ChatOptions { Tools = [.. tools] };

var topic = args.Length > 0 ? string.Join(' ', args) : "quantum computing";
Console.WriteLine($"📚 Researching topic: {topic}\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.System,
        """
        You are a research agent. Your job is to thoroughly research a given topic using the available tools.

        Follow this workflow:
        1. Search the web for information about the topic (perform 2-3 searches with different angles).
        2. Save important findings as notes using the note-taking tool, categorizing them appropriately.
        3. Retrieve all your notes and provide a comprehensive summary of your research.

        Be thorough but concise. Organize findings into clear categories.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a comprehensive summary: {topic}")
};

Console.WriteLine("🔍 Agent is researching...\n");

var response = await client.GetResponseAsync(messages, chatOptions);

Console.WriteLine("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");
Console.WriteLine("📋 Research Summary:");
Console.WriteLine("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");
Console.WriteLine(response.Text);
Console.WriteLine("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");

