 using OpenAI;

+// --- Main Program ---
+
+Console.WriteLine("🔬 Research Agent Starting...\n");
+
+var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "your-api-key-here";
+var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
+
+IChatClient client = new OpenAIClient(apiKey)
+    .GetChatClient(modelId)
+    .AsIChatClient()
+    .AsBuilder()
+    .UseFunctionInvocation()
+    .Build();
+
+var tools = new AITool[]
+{
+    AIFunctionFactory.Create(WebSearchTool.SearchWeb),
+    AIFunctionFactory.Create(NotesTool.SaveNote),
+    AIFunctionFactory.Create(NotesTool.GetAllNotes),
+};
+
+var chatOptions = new ChatOptions { Tools = [.. tools] };
+
+var topic = args.Length > 0 ? string.Join(' ', args) : "quantum computing";
+Console.WriteLine($"📚 Researching topic: {topic}\n");
+
+var messages = new List<ChatMessage>
+{
+    new(ChatRole.System,
+        """
+        You are a research agent. Your job is to thoroughly research a given topic using the available tools.
+        
+        Follow this workflow:
+        1. Search the web for information about the topic (perform 2-3 searches with different angles).
+        2. Save important findings as notes using the note-taking tool, categorizing them appropriately.
+        3. Retrieve all your notes and provide a comprehensive summary of your research.
+        
+        Be thorough but concise. Organize findings into clear categories.
+        """),
+    new(ChatRole.User, $"Please research the following topic and provide a comprehensive summary: {topic}")
+};
+
+Console.WriteLine("🔍 Agent is researching...\n");
+
+var response = await client.GetResponseAsync(messages, chatOptions);
+
+Console.WriteLine("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");
